def transform(g):
    h,w=len(g),len(g[0])
    cells=[(i,j,g[i][j]) for i in range(h) for j in range(w) if g[i][j]]
    # orientation: constant i (horizontal rows) or constant j-i (down-right diagonals)
    if len({i for i,j,v in cells})==len({(i,v) for i,j,v in cells}) and len({i for i,j,v in cells})<len({j-i for i,j,v in cells}):
        off=lambda i,j: i
    else:
        off=lambda i,j: j-i
    lines={}  # offset -> color (check consistency)
    for i,j,v in cells:
        o=off(i,j)
        if o in lines: assert lines[o]==v,(o,lines[o],v)
        lines[o]=v
    p=len(lines)
    res={}
    for o,c in lines.items():
        r=o%p
        assert r not in res
        res[r]=c
    return [[res[(off(i,j))%p] for j in range(w)] for i in range(h)]

